-- 로컬 H2(마이그레이션을 모두 적용한 DB)에서 최종 스키마를 CSV로 뽑는다. 저장소 루트에서 실행한다(README "스키마 다시 뽑기").
CALL CSVWRITE('docs/learning-guide/schema/cols.csv', 'SELECT table_name, column_name, data_type, character_maximum_length, is_nullable, column_default, ordinal_position FROM information_schema.columns WHERE table_schema=''public'' AND table_name <> ''flyway_schema_history'' ORDER BY table_name, ordinal_position', 'charset=UTF-8');
CALL CSVWRITE('docs/learning-guide/schema/cons.csv', 'SELECT tc.table_name, tc.constraint_name, tc.constraint_type, kcu.column_name, kcu.ordinal_position FROM information_schema.table_constraints tc JOIN information_schema.key_column_usage kcu ON kcu.constraint_name = tc.constraint_name AND kcu.table_name = tc.table_name WHERE tc.table_schema=''public'' AND tc.table_name <> ''flyway_schema_history'' ORDER BY tc.table_name, tc.constraint_name, kcu.ordinal_position', 'charset=UTF-8');
CALL CSVWRITE('docs/learning-guide/schema/refs.csv', 'SELECT rc.constraint_name, kcu2.table_name AS ref_table, kcu2.column_name AS ref_column, rc.delete_rule FROM information_schema.referential_constraints rc JOIN information_schema.key_column_usage kcu2 ON kcu2.constraint_name = rc.unique_constraint_name ORDER BY rc.constraint_name', 'charset=UTF-8');
CALL CSVWRITE('docs/learning-guide/schema/idx.csv', 'SELECT table_name, index_name, column_name, ordinal_position FROM information_schema.index_columns WHERE table_schema=''public'' AND table_name <> ''flyway_schema_history'' ORDER BY table_name, index_name, ordinal_position', 'charset=UTF-8');
